// csilEncPersonaRevision builds the canonical CBOR value tree for a PersonaRevision.
func csilEncPersonaRevision(csilV PersonaRevision) cborValue {
	csilEntries := make(cborMap, 0, 7)
	csilEntries = append(csilEntries, cborEntry{cborText("ref"), csilEncRevisionRef(csilV.Ref)})
	if csilV.Prior != nil {
		csilEntries = append(csilEntries, cborEntry{cborText("prior"), csilEncRevisionRef((*csilV.Prior))})
	}
	if csilV.Voice != nil {
		csilEntries = append(csilEntries, cborEntry{cborText("voice"), csilEncTypedPayload((*csilV.Voice))})
	}
	csilEntries = append(csilEntries, cborEntry{cborText("author"), csilEncIdentityRef(csilV.Author)})
	csilEntries = append(csilEntries, cborEntry{cborText("focuses"), cborEncArray(csilV.Focuses, func(csilElem string) cborValue { return cborText(csilElem) })})
	csilEntries = append(csilEntries, cborEntry{cborText("defaults"), csilEncRestrictions(csilV.Defaults)})
	csilEntries = append(csilEntries, cborEntry{cborText("personality"), csilEncArtifactRef(csilV.Personality)})
	return csilEntries
}

// csilDecPersonaRevision reconstructs a PersonaRevision from a decoded CBOR value tree.
func csilDecPersonaRevision(csilRoot cborValue) (PersonaRevision, error) {
	var csilOut PersonaRevision
	{
		csilField, csilErr := cborRequire(csilRoot, "ref")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (csilDecRevisionRef)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Ref = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "author")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (csilDecIdentityRef)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Author = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "personality")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (csilDecArtifactRef)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Personality = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "focuses")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (func(csilV cborValue) ([]string, error) { return cborDecArray(csilV, cborAsText) })(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Focuses = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "defaults")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (csilDecRestrictions)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Defaults = csilVal
	}
	if csilField, csilOk := cborMapGet(csilRoot, "voice"); csilOk {
		csilVal, csilErr := (csilDecTypedPayload)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Voice = &csilVal
	}
	if csilField, csilOk := cborMapGet(csilRoot, "prior"); csilOk {
		csilVal, csilErr := (csilDecRevisionRef)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Prior = &csilVal
	}
	return csilOut, nil
}

