// csilEncCommandResult builds the canonical CBOR value tree for a CommandResult.
func csilEncCommandResult(csilV CommandResult) cborValue {
	csilEntries := make(cborMap, 0, 6)
	csilEntries = append(csilEntries, cborEntry{cborText("effect"), cborText(csilV.Effect)})
	csilEntries = append(csilEntries, cborEntry{cborText("streams"), cborEncArray(csilV.Streams, func(csilElem RecordRef) cborValue { return csilEncRecordRef(csilElem) })})
	if csilV.ExitCode != nil {
		csilEntries = append(csilEntries, cborEntry{cborText("exit_code"), cborInt((*csilV.ExitCode))})
	}
	csilEntries = append(csilEntries, cborEntry{cborText("command_id"), cborText(csilV.CommandId)})
	csilEntries = append(csilEntries, cborEntry{cborText("evidence_capture"), cborText(csilV.EvidenceCapture)})
	if csilV.TerminationSignal != nil {
		csilEntries = append(csilEntries, cborEntry{cborText("termination_signal"), cborText((*csilV.TerminationSignal))})
	}
	return csilEntries
}

// csilDecCommandResult reconstructs a CommandResult from a decoded CBOR value tree.
func csilDecCommandResult(csilRoot cborValue) (CommandResult, error) {
	var csilOut CommandResult
	{
		csilField, csilErr := cborRequire(csilRoot, "command_id")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (cborAsText)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.CommandId = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "effect")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (func(csilV cborValue) (ReceiptState, error) {
			csilInner, csilErr := (func(csilV cborValue) (string, error) {
				csilInner, csilErr := (cborAsText)(csilV)
				if csilErr != nil {
					var csilZero string
					return csilZero, csilErr
				}
				if !(csilInner == "accepted" || csilInner == "completed" || csilInner == "rejected" || csilInner == "outcome_unknown") {
					var csilZero string
					return csilZero, fmt.Errorf("csil cbor: value %v is not a member of the declared enum", csilInner)
				}
				return csilInner, nil
			})(csilV)
			return ReceiptState(csilInner), csilErr
		})(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Effect = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "evidence_capture")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (func(csilV cborValue) (CaptureStatus, error) {
			csilInner, csilErr := (func(csilV cborValue) (string, error) {
				csilInner, csilErr := (cborAsText)(csilV)
				if csilErr != nil {
					var csilZero string
					return csilZero, csilErr
				}
				if !(csilInner == "complete" || csilInner == "incomplete" || csilInner == "unknown") {
					var csilZero string
					return csilZero, fmt.Errorf("csil cbor: value %v is not a member of the declared enum", csilInner)
				}
				return csilInner, nil
			})(csilV)
			return CaptureStatus(csilInner), csilErr
		})(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.EvidenceCapture = csilVal
	}
	{
		csilField, csilErr := cborRequire(csilRoot, "streams")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (func(csilV cborValue) ([]RecordRef, error) { return cborDecArray(csilV, csilDecRecordRef) })(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Streams = csilVal
	}
	if csilField, csilOk := cborMapGet(csilRoot, "exit_code"); csilOk {
		csilVal, csilErr := (cborAsI64)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.ExitCode = &csilVal
	}
	if csilField, csilOk := cborMapGet(csilRoot, "termination_signal"); csilOk {
		csilVal, csilErr := (cborAsText)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.TerminationSignal = &csilVal
	}
	return csilOut, nil
}

